26	constexpr int64_t CAST_PACK2 = 2;
27	
28	constexpr int64_t B2_BITS = 2;
29	constexpr int64_t B4_BITS = 4;
30	constexpr int64_t B7_BITS = 7;
31	constexpr int64_t B8_BITS = 8;
32	constexpr int64_t B12_BITS = 12;
33	constexpr int64_t B13_BITS = 13;
34	constexpr int64_t B16_BITS = 16;
35	constexpr int64_t B32_BITS = 32;
36	constexpr int64_t B64_BITS = 64;
37	
38	constexpr int64_t PER_CORE_MIN_UB_BIT = 4 * 1024 * 8;
39	constexpr uint32_t MINIMAL_WORKSPACE = 16 * 1024 * 1024;
40	constexpr int32_t SIMT_RESERVED_SIZE = 32 * 1024;
41	
42	constexpr int64_t UB_ALIGN_RESERVE_TYPE1 = 32 * 6;
43	constexpr int64_t UB_ALIGN_RESERVE_TYPE2 = 32 * 5;
44	constexpr int64_t UB_ALIGN_RESERVE_TYPE3 = 32 * 5;
45	constexpr int64_t UB_ALIGN_RESERVE_TYPE4 = 32 * 4;
