49	ge::graphStatus CastTiling::GetPlatformInfo()
50	{
51	    auto platformInfo = context_->GetPlatformInfo();
52	    if (platformInfo == nullptr) {
53	        auto compileInfoPtr = context_->GetCompileInfo<CastCompileInfo>();
54	        OP_CHECK_IF(compileInfoPtr == nullptr,
55	                    OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "compile_info", "nullptr", "not nullptr"),
56	                    return ge::GRAPH_FAILED);
57	        coreNum_ = compileInfoPtr->coreNum;
58	        ubSize_ = compileInfoPtr->ubSize;
59	    } else {
60	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
61	        coreNum_ = ascendcPlatform.GetCoreNumAiv();
62	        uint64_t ubSizePlatForm = 0;
63	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
64	        ubSize_ = ubSizePlatForm;
65	    }
66	
67	    vlBitSize_ = static_cast<int64_t>(Ops::Base::GetVRegSize(context_) * B8_BITS);
68	    return ge::GRAPH_SUCCESS;
69	}
