71	ge::DataType CastTiling::TransAclToGeDataType(int32_t aclType) const
72	{
73	    switch (aclType) {
74	        case 0:
75	            return ge::DT_FLOAT;
76	        case 1: // 1 DT_FLOAT16
77	            return ge::DT_FLOAT16;
78	        case 2: // 2 DT_INT8
79	            return ge::DT_INT8;
80	        case 3: // 3 DT_INT32
81	            return ge::DT_INT32;
82	        case 4: // 4 DT_UINT8
83	            return ge::DT_UINT8;
84	        case 6: // 6 DT_INT16
85	            return ge::DT_INT16;
86	        case 7: // 7 DT_UINT16
87	            return ge::DT_UINT16;
88	        case 8: // 8 DT_UINT32
89	            return ge::DT_UINT32;
90	        case 9: // 9 DT_INT64
91	            return ge::DT_INT64;
92	        case 10: // 10 DT_UINT64
93	            return ge::DT_UINT64;
94	        case 11: // 11 DT_DOUBLE
95	            return ge::DT_DOUBLE;
96	        case 12: // 12 DT_BOOL
97	            return ge::DT_BOOL;
98	        case 16: // 16 DT_COMPLEX64
99	            return ge::DT_COMPLEX64;
100	        case 27: // 27 DT_BF16
101	            return ge::DT_BF16;
102	        case 29: // 29 DT_INT4
103	            return ge::DT_INT4;
104	        case 33: // 33 DT_COMPLEX32
105	            return ge::DT_COMPLEX32;
106	        case 34: // 34 DT_HIFLOAT8
107	            return ge::DT_HIFLOAT8;
108	        case 35: // 35 DT_FLOAT8_E5M2
109	            return ge::DT_FLOAT8_E5M2;
110	        case 36: // 36 DT_FLOAT8_E4M3FN
111	            return ge::DT_FLOAT8_E4M3FN;
112	        case 40: // 40 DT_FLOAT4_E2M1
113	            return ge::DT_FLOAT4_E2M1;
114	        case 41: // 41 DT_FLOAT4_E1M2
115	            return ge::DT_FLOAT4_E1M2;
116	        default:
117	            return ge::DT_MAX;
118	    }
119	}
