121	ge::graphStatus CastTiling::GetShapeAttrsInfo()
122	{
123	    OP_CHECK_IF((context_ == nullptr), OP_LOGE_FOR_INVALID_VALUE("Cast", "context", "nullptr", "not nullptr"),
124	                return ge::GRAPH_FAILED);
125	
126	    auto xDesc = context_->GetInputDesc(0);
127	    OP_CHECK_NULL_WITH_CONTEXT(context_, xDesc);
128	    ge::DataType xDtype = xDesc->GetDataType();
129	
130	    auto yDesc = context_->GetOutputDesc(0);
131	    OP_CHECK_NULL_WITH_CONTEXT(context_, yDesc);
132	    ge::DataType yDtype = yDesc->GetDataType();
133	
134	    // 判断属性和目的类型一致
135	    auto runtimeAttrs = context_->GetAttrs();
136	    OP_CHECK_NULL_WITH_CONTEXT(context_, runtimeAttrs);
137	    const int32_t* dstTypePtr = runtimeAttrs->GetAttrPointer<int32_t>(0);
138	    OP_CHECK_IF((dstTypePtr == nullptr),
139	                OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "dst_type_attr", "nullptr", "not nullptr"),
140	                return ge::GRAPH_FAILED);
141	    ge::DataType dstDtype = TransAclToGeDataType(*dstTypePtr);
142	    OP_CHECK_IF((dstDtype == ge::DT_MAX),
143	                OP_LOGE_FOR_INVALID_DTYPE_WITH_REASON(context_->GetNodeName(), "dst_type",
144	                                                      ge::TypeUtils::DataTypeToSerialString(dstDtype),
145	                                                      "The dtype of dst_type must be in the supported dtype list"),
146	                return ge::GRAPH_FAILED);
147	    OP_CHECK_IF(
148	        (dstDtype != yDtype),
149	        OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(context_->GetNodeName(), "dst_type, y",
150	                                               std::string(ge::TypeUtils::DataTypeToSerialString(dstDtype)) + ", " +
151	                                                   std::string(ge::TypeUtils::DataTypeToSerialString(yDtype)),
152	                                               "The dtypes of dst_type and y must be the same"),
153	        return ge::GRAPH_FAILED);
154	
155	    // 表驱动，也校验了是否是支持的转换
156	    constexpr int arraySize = sizeof(castMap) / sizeof(CastMapSt);
157	    auto it = std::find_if(castMap, castMap + arraySize, [xDtype, yDtype](const CastMapSt& v) {
158	        return v.srcType_ == xDtype && v.dstType_ == yDtype;
159	    });
160	    if (it != castMap + arraySize) {
161	        policy_ = *it;
162	    } else {
163	        OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(context_->GetNodeName(), "x, y",
164	                                               std::string(ge::TypeUtils::DataTypeToSerialString(xDtype)) + ", " +
165	                                                   std::string(ge::TypeUtils::DataTypeToSerialString(yDtype)),
166	                                               "Dtype conversion from x to y is not supported");
167	        return ge::GRAPH_FAILED;
168	    }
169	
170	    auto outputShape = context_->GetOutputShape(0);
171	    OP_CHECK_NULL_WITH_CONTEXT(context_, outputShape);
172	    auto outShape = outputShape->GetStorageShape();
173	    auto inputShape = context_->GetInputShape(0);
174	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputShape);
175	    auto inShape = inputShape->GetStorageShape();
176	    size_t xDimNum = inShape.GetDimNum();
177	    if (dstDtype == ge::DT_INT4 && (inShape.GetDim(xDimNum - 1) % CAST_PACK2)) {
178	        OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON(context_->GetNodeName(), "x[last_dim]",
179	                                                 std::to_string(inShape.GetDim(xDimNum - 1)),
180	                                                 "when dst_type is DT_INT4, last dim must be divisible by 2");
181	        return ge::GRAPH_FAILED;
182	    }
183	    if (!Ops::Base::IsSameElewiseShape(outShape, inShape)) {
184	        OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(
185	            context_->GetNodeName(), "x, y",
186	            (Ops::Base::ToString(inShape) + ", " + Ops::Base::ToString(outShape)).c_str(),
187	            "The shapes of x and y must be the same");
188	        return ge::GRAPH_FAILED;
189	    }
190	
191	    shapeSize_ = inShape.GetShapeSize();
192	    OP_CHECK_IF(shapeSize_ <= 0,
193	                OP_LOGE_FOR_INVALID_SHAPESIZE_WITH_REASON(context_->GetNodeName(), "x", std::to_string(shapeSize_),
194	                                                          "x does not support empty tensor"),
195	                return ge::GRAPH_FAILED);
196	
197	    return ge::GRAPH_SUCCESS;
198	}
