200	bool CastTiling::IsSimt() const
201	{
202	    if (policy_.id_ != CAST_TEMPLATE_DIRECT_CAST) {
203	        return false;
204	    }
205	    if (policy_.dstType_ == DT_DOUBLE && policy_.srcType_ == DT_INT64) {
206	        return true;
207	    }
208	    return false;
209	}
210	
211	int64_t CastTiling::GetUbFormer(int64_t inputTypeBitSize, int64_t outputTypeBitSize)
212	{
213	    int64_t alignInputNum = vlBitSize_ / inputTypeBitSize;
214	    OP_CHECK_IF(
215	        alignInputNum == 0,
216	        OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "vlBitSize", std::to_string(vlBitSize_), "greater than 0"),
217	        return 0);
218	    if (IsSimt()) {
219	        OP_LOGI(context_->GetNodeName(), "is SIMT, ub reserve 32k");
220	        ubSize_ = ubSize_ - SIMT_RESERVED_SIZE;
221	        context_->SetLocalMemorySize(ubSize_);
222	    }
223	    if (policy_.id_ == CAST_TEMPLATE_DIRECT_CAST || policy_.id_ == CAST_TEMPLATE_THROUGH ||
224	        policy_.id_ == CAST_TEMPLATE_MIRCRO_INOUT || policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST ||
225	        policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_INTER || policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_DEINTER ||
226	        policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_CAST_DEINTER || policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_CAST ||
227	        policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_INTER_CAST || policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_DEINTER_CAST ||
228	        policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_CAST_DEINTER_CAST ||
229	        policy_.id_ == CAST_TEMPLATE_MIRCRO_CAST_INTER_CAST_CAST || policy_.id_ == CAST_TEMPLATE_MIRCRO_DEINTER_SHIFT) {
230	        OP_CHECK_IF(ubSize_ <= UB_ALIGN_RESERVE_TYPE4,
231	                    OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_),
232	                                              "greater than UB_ALIGN_RESERVE_TYPE4"),
233	                    return 0);
234	        int64_t ubCap = ((ubSize_ - UB_ALIGN_RESERVE_TYPE4) * B4_BITS) / (inputTypeBitSize + outputTypeBitSize);
235	        return ubCap / alignInputNum * alignInputNum;
236	    } else if (policy_.id_ == CAST_TEMPLATE_DST_BOOL) {
237	        OP_CHECK_IF(ubSize_ <= UB_ALIGN_RESERVE_TYPE1,
238	                    OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_),
239	                                              "greater than UB_ALIGN_RESERVE_TYPE1"),
240	                    return 0);
241	        int64_t ubCap = ((ubSize_ - UB_ALIGN_RESERVE_TYPE1) * B4_BITS) / (inputTypeBitSize + B13_BITS);
242	        return ubCap / alignInputNum * alignInputNum;
243	    } else if (policy_.id_ == CAST_TEMPLATE_SRC_UINT1) {
244	        OP_CHECK_IF(ubSize_ <= UB_ALIGN_RESERVE_TYPE2,
245	                    OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_),
246	                                              "greater than UB_ALIGN_RESERVE_TYPE2"),
247	                    return 0);
248	        int64_t ubCap = ((ubSize_ - UB_ALIGN_RESERVE_TYPE2) * B4_BITS) / (outputTypeBitSize * B12_BITS / B8_BITS + 1);
249	        return ubCap / alignInputNum * alignInputNum;
250	    } else if (policy_.id_ == CAST_TEMPLATE_TWO_CAST) {
251	        int64_t midTypeBitSize = GetDtypeBitSize(policy_.midType_);
252	        OP_CHECK_IF(midTypeBitSize == 0, OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "midType", "0", "not 0"),
253	                    return 0);
254	        OP_CHECK_IF(ubSize_ <= UB_ALIGN_RESERVE_TYPE3,
255	                    OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_),
256	                                              "greater than UB_ALIGN_RESERVE_TYPE3"),
257	                    return 0);
258	        int64_t ubCap = ((ubSize_ - UB_ALIGN_RESERVE_TYPE3) * B4_BITS) /
259	                        (inputTypeBitSize + outputTypeBitSize + midTypeBitSize);
260	        return ubCap / alignInputNum * alignInputNum;
261	    }
262	    return 0;
263	}
264	
265	int64_t CastTiling::GetDtypeBitSize(uint8_t dtype) const
266	{
267	    if (dtype == CAST_TPL_UINT1) {
268	        return 1;
269	    } else if (dtype == CAST_TPL_BOOL || dtype == CAST_TPL_INT8 || dtype == CAST_TPL_UINT8 ||
270	               dtype == CAST_TPL_FLOAT8_E4M3FN || dtype == CAST_TPL_FLOAT8_E5M2 || dtype == CAST_TPL_HIFLOAT8) {
271	        return B8_BITS;
272	    } else if (dtype == CAST_TPL_UINT16 || dtype == CAST_TPL_INT16 || dtype == CAST_TPL_FLOAT16 ||
273	               dtype == CAST_TPL_BF16) {
274	        return B16_BITS;
275	    } else if (dtype == CAST_TPL_COMPLEX32 || dtype == CAST_TPL_FLOAT || dtype == CAST_TPL_INT32 ||
276	               dtype == CAST_TPL_UINT32) {
277	        return B32_BITS;
278	    } else if (dtype == CAST_TPL_COMPLEX64 || dtype == CAST_TPL_INT64 || dtype == CAST_TPL_DOUBLE) {
279	        return B64_BITS;
280	    } else if (dtype == CAST_TPL_FLOAT4_E2M1 || dtype == CAST_TPL_FLOAT4_E1M2 || dtype == CAST_TPL_INT4) {
281	        return B4_BITS;
282	    }
283	    return 0;
284	}
285	
286	int64_t CastTiling::GetGeDtypeBitSize(ge::DataType dtype) const
287	{
288	    if (dtype == DT_UINT1) {
289	        return 1;
290	    } else if (dtype == DT_BOOL || dtype == DT_INT8 || dtype == DT_UINT8 || dtype == DT_FLOAT8_E4M3FN ||
291	               dtype == DT_FLOAT8_E5M2 || dtype == DT_HIFLOAT8) {
292	        return B8_BITS;
293	    } else if (dtype == DT_UINT16 || dtype == DT_INT16 || dtype == DT_FLOAT16 || dtype == DT_BF16) {
294	        return B16_BITS;
295	    } else if (dtype == DT_COMPLEX32 || dtype == DT_FLOAT || dtype == DT_INT32 || dtype == DT_UINT32) {
296	        return B32_BITS;
297	    } else if (dtype == DT_COMPLEX64 || dtype == DT_INT64 || dtype == DT_DOUBLE) {
298	        return B64_BITS;
299	    } else if (dtype == DT_FLOAT4_E2M1 || dtype == DT_FLOAT4_E1M2 || dtype == DT_INT4) {
300	        return B4_BITS;
301	    }
302	    return 0;
303	}
304	
305	ge::graphStatus CastTiling::DoOpTiling()
306	{
307	    int64_t inputTypeBitSize = GetGeDtypeBitSize(policy_.srcType_);
308	    OP_CHECK_IF(inputTypeBitSize == 0,
309	                OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "inputTypeBitSize", std::to_string(inputTypeBitSize),
310	                                          "not 0"),
311	                return ge::GRAPH_FAILED);
312	
313	    int64_t outputTypeBitSize = GetGeDtypeBitSize(policy_.dstType_);
314	    OP_CHECK_IF(outputTypeBitSize == 0,
315	                OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "outputTypeBitSize",
316	                                          std::to_string(outputTypeBitSize), "not 0"),
317	                return ge::GRAPH_FAILED);
318	
319	    ubFormer_ = GetUbFormer(inputTypeBitSize, outputTypeBitSize);
320	    OP_CHECK_IF(ubFormer_ == 0,
321	                OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_), "greater than 0"),
322	                return ge::GRAPH_FAILED);
323	
324	    int64_t coreNum = (shapeSize_ * inputTypeBitSize + PER_CORE_MIN_UB_BIT - 1) / PER_CORE_MIN_UB_BIT;
325	    if (coreNum > coreNum_) {
326	        coreNum = coreNum_;
327	    }
328	    OP_CHECK_IF(coreNum <= 0,
329	                OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "coreNum",
330	                                          std::to_string(coreNum) + "," + std::to_string(coreNum_),
331	                                          "in the range [1, sys_core_num]"),
332	                return ge::GRAPH_FAILED);
333	    usedCoreNum_ = coreNum;
334	
335	    OP_LOGD(context_->GetNodeName(),
336	            "cast do tiling finish. coreNum: %ld ubSize: %ld vlBit: %ld shapeSize: %ld usedCoreNum: %ld ubFormer: %ld",
337	            coreNum_, ubSize_, vlBitSize_, shapeSize_, usedCoreNum_, ubFormer_);
338	    return ge::GRAPH_SUCCESS;
339	}
