349	ge::graphStatus CastTiling::GetWorkspaceSize()
350	{
351	    workspaceSize_ = MINIMAL_WORKSPACE;
352	    return ge::GRAPH_SUCCESS;
353	}
354	
355	ge::graphStatus CastTiling::PostTiling()
356	{
357	    OP_CHECK_IF(static_cast<size_t>(sizeof(CastTilingData)) > context_->GetRawTilingData()->GetCapacity(),
358	                OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(
359	                    context_->GetNodeName(), "tiling_data_size", std::to_string(sizeof(CastTilingData)),
360	                    "The value of tiling_data_size must be less than or equal to capacity"),
361	                return ge::GRAPH_FAILED);
362	
363	    CastTilingData* tiling = context_->GetTilingData<CastTilingData>();
364	    OP_CHECK_NULL_WITH_CONTEXT(context_, tiling);
365	    tiling->shapeSize = shapeSize_;
366	    tiling->coreNum = static_cast<int32_t>(usedCoreNum_);
367	    tiling->ubFormer = static_cast<int32_t>(ubFormer_);
368	
369	    int64_t blockFormer = ((shapeSize_ + usedCoreNum_ - 1) / usedCoreNum_ + B7_BITS) / B8_BITS * B8_BITS;
370	    int64_t blockNum = (shapeSize_ + blockFormer - 1) / blockFormer;
371	
372	    size_t* currentWorkspace = context_->GetWorkspaceSizes(1);
373	    OP_CHECK_NULL_WITH_CONTEXT(context_, currentWorkspace);
374	    currentWorkspace[0] = workspaceSize_;
375	
376	    uint64_t tilingKey = GetTilingKey();
377	    context_->SetTilingKey(tilingKey);
378	    context_->SetBlockDim(blockNum);
379	    return ge::GRAPH_SUCCESS;
380	}
381	
382	static ge::graphStatus TilingForCast(gert::TilingContext* context)
383	{
384	    OP_LOGD("CastTiling", "Enter TilingForCast");
385	    OP_CHECK_IF(context == nullptr, OP_LOGE_FOR_INVALID_VALUE("Cast", "context", "nullptr", "not nullptr"),
386	                return ge::GRAPH_FAILED);
387	
388	    auto compileInfo = context->GetCompileInfo<CastCompileInfo>();
389	    OP_CHECK_NULL_WITH_CONTEXT(context, compileInfo);
390	    OP_LOGD("CastTiling", "Enter new CastTiling");
391	    return Ops::Math::OpTiling::TilingRegistry::GetInstance().DoTilingImpl(context);
392	}
393	
394	static ge::graphStatus TilingPrepareForCast(gert::TilingParseContext* context)
395	{
396	    auto compileInfoPtr = context->GetCompiledInfo<CastCompileInfo>();
397	    OP_CHECK_NULL_WITH_CONTEXT(context, compileInfoPtr);
398	    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
399	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
400	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
401	    compileInfoPtr->coreNum = ascendcPlatform.GetCoreNumAiv();
402	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
403	    return ge::GRAPH_SUCCESS;
404	}
405	
406	IMPL_OP_OPTILING(Cast).Tiling(TilingForCast).TilingParse<CastCompileInfo>(TilingPrepareForCast);
407	
408	REGISTER_OPS_TILING_TEMPLATE(Cast, CastTiling, 1);
409	} // namespace optiling
