126	constexpr int64_t B4_BITS = 4;
127	constexpr int64_t B12_BITS = 12;
128	constexpr int64_t B13_BITS = 13;
129	constexpr int64_t B16_BITS = 16;
130	constexpr int64_t B32_BITS = 32;
131	constexpr int64_t B64_BITS = 64;
132	constexpr int64_t CAST_PACK2 = 2;
133	constexpr int64_t CAST_PACK4 = 4;
134	
135	__aicore__ constexpr inline int64_t GetTplBitSize(int dtype)
136	{
137	    if (dtype == CAST_TPL_UINT1) {
138	        return 1;
139	    } else if (dtype == CAST_TPL_BOOL || dtype == CAST_TPL_INT8 || dtype == CAST_TPL_UINT8 ||
140	               dtype == CAST_TPL_FLOAT8_E4M3FN || dtype == CAST_TPL_FLOAT8_E5M2 || dtype == CAST_TPL_HIFLOAT8) {
141	        return B8_BITS;
142	    } else if (dtype == CAST_TPL_UINT16 || dtype == CAST_TPL_INT16 || dtype == CAST_TPL_FLOAT16 ||
143	               dtype == CAST_TPL_BF16) {
144	        return B16_BITS;
145	    } else if (dtype == CAST_TPL_COMPLEX32 || dtype == CAST_TPL_FLOAT || dtype == CAST_TPL_INT32 ||
146	               dtype == CAST_TPL_UINT32) {
147	        return B32_BITS;
148	    } else if (dtype == CAST_TPL_COMPLEX64 || dtype == CAST_TPL_INT64 || dtype == CAST_TPL_DOUBLE) {
149	        return B64_BITS;
150	    } else if (dtype == CAST_TPL_FLOAT4_E2M1 || dtype == CAST_TPL_FLOAT4_E1M2 || dtype == CAST_TPL_INT4) {
151	        return B4_BITS;
152	    }
153	    return 0;
154	}
155	
156	__aicore__ constexpr inline int64_t GetGeBitSize(int dtype)
157	{
158	    if (dtype == DT_UINT1) {
159	        return 1;
160	    } else if (dtype == DT_BOOL || dtype == DT_INT8 || dtype == DT_UINT8 || dtype == DT_FLOAT8_E4M3FN ||
161	               dtype == DT_FLOAT8_E5M2 || dtype == DT_HIFLOAT8) {
162	        return B8_BITS;
163	    } else if (dtype == DT_UINT16 || dtype == DT_INT16 || dtype == DT_FLOAT16 || dtype == DT_BF16) {
164	        return B16_BITS;
165	    } else if (dtype == DT_COMPLEX32 || dtype == DT_FLOAT || dtype == DT_INT32 || dtype == DT_UINT32) {
166	        return B32_BITS;
167	    } else if (dtype == DT_COMPLEX64 || dtype == DT_INT64 || dtype == DT_DOUBLE) {
168	        return B64_BITS;
169	    } else if (dtype == DT_FLOAT4_E2M1 || dtype == DT_FLOAT4_E1M2 || dtype == DT_INT4) {
170	        return B4_BITS;
171	    }
172	    return 0;
173	}
