175	struct UbCopyStepResult {
176	    int64_t step;
177	    int64_t oneLoopCopyInBitSize;
178	};
179	
180	__aicore__ constexpr inline UbCopyStepResult GetUbCopyInStep(int copyMode, int inType)
181	{
182	    if (copyMode == CAST_MODE_REG_COPYIN_NORM) {
183	        return {VL_BIT_SIZE / GetTplBitSize(inType), VL_BIT_SIZE};
184	    } else if (copyMode == CAST_MODE_REG_COPYIN_DS_B8) {
185	        return {VL_BIT_SIZE * CAST_PACK2 / B8_BITS, VL_BIT_SIZE * CAST_PACK2};
186	    } else if (copyMode == CAST_MODE_REG_COPYIN_DS_B16) {
187	        return {VL_BIT_SIZE * CAST_PACK2 / B16_BITS, VL_BIT_SIZE * CAST_PACK2};
188	    } else if (copyMode == CAST_MODE_REG_COPYIN_UNPACK_B8) {
189	        return {VL_BIT_SIZE / CAST_PACK2 / B8_BITS, VL_BIT_SIZE / CAST_PACK2};
190	    } else if (copyMode == CAST_MODE_REG_COPYIN_UNPACK_B16) {
191	        return {VL_BIT_SIZE / CAST_PACK2 / B16_BITS, VL_BIT_SIZE / CAST_PACK2};
192	    } else if (copyMode == CAST_MODE_REG_COPYIN_UNPACK_B32) {
193	        return {VL_BIT_SIZE / CAST_PACK2 / B32_BITS, VL_BIT_SIZE / CAST_PACK2};
194	    } else if (copyMode == CAST_MODE_REG_COPYIN_UNPACK4_B8) {
195	        return {VL_BIT_SIZE / CAST_PACK4 / B8_BITS, VL_BIT_SIZE / CAST_PACK4};
196	    }
197	    return {0, 0};
198	}
199	
200	__aicore__ constexpr inline int64_t GetUbCopyOutStep(int copyMode, int outType)
201	{
202	    if (copyMode == CAST_MODE_REG_COPYOUT_NORM) {
203	        return VL_BIT_SIZE / GetTplBitSize(outType);
204	    } else if (copyMode == CAST_MODE_REG_COPYOUT_PACK_B16) {
205	        return VL_BIT_SIZE / B16_BITS / CAST_PACK2;
206	    } else if (copyMode == CAST_MODE_REG_COPYOUT_PACK_B32) {
207	        return VL_BIT_SIZE / B32_BITS / CAST_PACK2;
208	    } else if (copyMode == CAST_MODE_REG_COPYOUT_PACK_B64) {
209	        return VL_BIT_SIZE / B64_BITS / CAST_PACK2;
210	    } else if (copyMode == CAST_MODE_REG_COPYOUT_PACK4_B32) {
211	        return VL_BIT_SIZE / B32_BITS / CAST_PACK4;
212	    }
213	    return 0;
214	}
