216	struct CastDerivedTiling {
217	    int64_t blockFormer;
218	    int64_t blockNum;
219	    int64_t blockTail;
220	    int64_t ubLoopOfFormerBlock;
221	    int64_t ubLoopOfTailBlock;
222	    int64_t ubTailOfFormerBlock;
223	    int64_t ubTailOfTailBlock;
224	};
225	
226	__aicore__ inline CastDerivedTiling ComputeCastDerivedTiling(int64_t shapeSize, int64_t coreNum, int64_t ubFormer)
227	{
228	    CastDerivedTiling d;
229	    d.blockFormer = ((shapeSize + coreNum - 1) / coreNum + B7_BITS) / B8_BITS * B8_BITS;
230	    d.blockNum = (shapeSize + d.blockFormer - 1) / d.blockFormer;
231	    d.blockTail = shapeSize - (d.blockNum - 1) * d.blockFormer;
232	    d.ubLoopOfFormerBlock = (d.blockFormer + ubFormer - 1) / ubFormer;
233	    d.ubLoopOfTailBlock = (d.blockTail + ubFormer - 1) / ubFormer;
234	    d.ubTailOfFormerBlock = d.blockFormer - (d.ubLoopOfFormerBlock - 1) * ubFormer;
235	    d.ubTailOfTailBlock = d.blockTail - (d.ubLoopOfTailBlock - 1) * ubFormer;
236	    return d;
237	}
