283	    yGm_.SetGlobalBuffer((__gm__ DT*)y + gmBlockOffset);
284	
285	    pipe_->InitBuffer(inQueueX_, bufferNum_, tilingData_->ubFormer * sizeof(ST));
286	    pipe_->InitBuffer(outQueue_, bufferNum_, tilingData_->ubFormer * sizeof(DT));
287	
288	    dataCopyInParams_.blockCount = 1;
289	    dataCopyInParams_.blockLen = 0;
290	    dataCopyInParams_.srcStride = 0;
291	    dataCopyInParams_.dstStride = 0;
