311	template <typename ST, typename DT>
312	__aicore__ inline void CastDirect<ST, DT>::Compute(int64_t len)
313	{
314	    auto xLocal = inQueueX_.template DeQue<ST>();
315	    auto yLocal = outQueue_.template AllocTensor<DT>();
316	    Cast<DT, ST>(yLocal, xLocal, rMode_, len);
