329	template <typename ST, typename DT>
330	__aicore__ inline void CastDirect<ST, DT>::Process()
331	{
332	    bool isLastBlockFlag = (blockIdx_ == derived_.blockNum - 1);
333	    int64_t loopNum = isLastBlockFlag ? derived_.ubLoopOfTailBlock : derived_.ubLoopOfFormerBlock;
334	    int64_t tailNum = isLastBlockFlag ? derived_.ubTailOfTailBlock : derived_.ubTailOfFormerBlock;
335	
336	    int64_t gmOffset = 0;
337	    dataCopyInParams_.blockLen = tilingData_->ubFormer * sizeof(ST);
338	    dataCopyOutParams_.blockLen = tilingData_->ubFormer * sizeof(DT);
339	    for (int64_t i = 0; i < loopNum - 1; ++i) {
340	        CopyIn(gmOffset);
341	        Compute(tilingData_->ubFormer);
342	        CopyOut(gmOffset);
343	        gmOffset += tilingData_->ubFormer;
344	    }
345	
346	    dataCopyInParams_.blockLen = tailNum * sizeof(ST);
347	    dataCopyOutParams_.blockLen = tailNum * sizeof(DT);
348	    CopyIn(gmOffset);
349	    Compute(tailNum);
350	    CopyOut(gmOffset);
351	}
