681	__aicore__ inline void CastUint1<DT>::Process()
682	{
683	    bool isLastBlockFlag = (blockIdx_ == derived_.blockNum - 1);
684	    int64_t loopNum = isLastBlockFlag ? derived_.ubLoopOfTailBlock : derived_.ubLoopOfFormerBlock;
685	    int64_t tailNum = isLastBlockFlag ? derived_.ubTailOfTailBlock : derived_.ubTailOfFormerBlock;
686	
687	    int64_t gmOffset = 0;
688	    dataCopyInParams_.blockLen = tilingData_->ubFormer / B8_BITS;
689	    dataCopyOutParams_.blockLen = tilingData_->ubFormer * sizeof(DT);
690	    for (int64_t i = 0; i < loopNum - 1; ++i) {
691	        CopyIn(gmOffset);
692	        Compute(tilingData_->ubFormer);
693	        CopyOut(gmOffset);
694	        gmOffset += tilingData_->ubFormer;
695	    }
696	
697	    dataCopyInParams_.blockLen = (tilingData_->ubFormer + B7_BITS) / B8_BITS;
698	    dataCopyOutParams_.blockLen = tailNum * sizeof(DT);
699	    CopyIn(gmOffset);
700	    Compute(tailNum);
701	    CopyOut(gmOffset);
702	}
