791	        Cast<DT, int32_t>(yLocal, tempTensor, rMode1_, len);
792	    } else if constexpr (std::is_same<MT, uint32_t>::value && std::is_same<DT, half>::value) {
793	        LocalTensor<int32_t> tempTensor = midLocal.template ReinterpretCast<int32_t>();
794	        Cast<DT, int32_t>(yLocal, tempTensor, rMode2_, len);
795	    } else if constexpr (std::is_same<MT, uint32_t>::value && std::is_same<DT, float>::value) {
796	        LocalTensor<int32_t> tempTensor = midLocal.template ReinterpretCast<int32_t>();
797	        Cast<DT, int32_t>(yLocal, tempTensor, rMode2_, len);
798	    } else {
799	        Cast<DT, MT>(yLocal, midLocal, rMode2_, len);
800	    }
801	    outQueue_.EnQue(yLocal);
