1011	    __ubuf__ MST* srcAddr = (__ubuf__ MST*)xLocal.GetPhyAddr();
1012	    __ubuf__ MDT* dstAddr = (__ubuf__ MDT*)yLocal.GetPhyAddr();
1013	    int32_t regCopyInStep = RegCopyInStep;
1014	    int32_t regCopyOutStep = RegCopyOutStep;
1015	    uint32_t count = static_cast<uint32_t>(len);
1016	
1017	    __VEC_SCOPE__
1018	    {
1019	        Reg::RegTensor<MST> vregTemp;
1020	        Reg::MaskReg mask;
1021	
1022	        for (uint16_t loopIdx = 0; loopIdx < regLoop; loopIdx++) {
1023	            mask = Reg::UpdateMask<MDT>(count);
1024	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregTemp, srcAddr, regCopyInStep);
1025	            Reg::DataCopy<MDT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, (Reg::RegTensor<MDT>&)vregTemp,
1026	                                                                           regCopyOutStep, mask);
1027	        }
1028	    }
1029	
1030	    inQueueX_.FreeTensor(xLocal);
