1040	{
1041	    auto xLocal = inQueueX_.template DeQue<ST>();
1042	    auto yLocal = outQueue_.template AllocTensor<DT>();
1043	    __ubuf__ MST* srcAddr = (__ubuf__ MST*)xLocal.GetPhyAddr();
1044	    __ubuf__ MDT* dstAddr = (__ubuf__ MDT*)yLocal.GetPhyAddr();
1045	    int32_t regCopyInStep = RegCopyInStep;
1046	    int32_t regCopyOutStep = RegCopyOutStep;
1047	    uint32_t count = static_cast<uint32_t>(len);
1048	
1049	    if constexpr (std::is_same<MST, uint32_t>::value && std::is_same<MDT, float>::value) {
1050	        regCopyOutStep = regCopyOutStep * 2;
1051	    }
1052	
1053	    static constexpr Reg::CastTrait trait = []() {
1054	        if constexpr (std::is_same<MST, bfloat16_t>::value && std::is_same<MMT, int32_t>::value) {
1055	            return Reg::CastTrait{RegLayout::ZERO, SatMode::SAT, MaskMergeMode::ZEROING, castMode1};
1056	        } else if constexpr (std::is_same<MST, half>::value && std::is_same<MMT, int32_t>::value) {
1057	            return Reg::CastTrait{RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING, castMode1};
1058	        } else if constexpr (std::is_same<MST, float>::value && std::is_same<MMT, int32_t>::value) {
1059	            return Reg::CastTrait{RegLayout::UNKNOWN, SatMode::SAT, MaskMergeMode::ZEROING, castMode1};
1060	        } else { // 默认用fp4 转换的trait
1061	            return Reg::CastTrait{RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING, castMode1};
1062	        }
1063	    }();
1064	
1065	    __VEC_SCOPE__
1066	    {
1067	        Reg::RegTensor<MST> vregIn;
1068	        Reg::RegTensor<MMT> vregOut;
1069	        Reg::MaskReg mask;
1070	        Reg::MaskReg maskAll = Reg::CreateMask<MST>();
