1440	            return Reg::CastTrait{RegLayout::ZERO, SatMode::SAT, MaskMergeMode::ZEROING, castMode2};
1441	        }
1442	    }();
1443	
1444	    __VEC_SCOPE__
1445	    {
1446	        Reg::RegTensor<MST> vregIn1;
1447	        Reg::RegTensor<MST> vregIn2;
1448	        Reg::RegTensor<MMT> vregMid1;
1449	        Reg::RegTensor<MMT> vregMid2;
1450	        Reg::RegTensor<MMT> vregDeinter;
1451	        Reg::RegTensor<MMT> vregDeinterNoUse;
1452	        Reg::RegTensor<MDT> vregOut;
1453	        Reg::MaskReg mask;
1454	        Reg::MaskReg maskAll = Reg::CreateMask<uint8_t>();
1455	
1456	        for (uint16_t loopIdx = 0; loopIdx < regLoop; loopIdx++) {
1457	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn1, srcAddr, regCopyInStep);
1458	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn2, srcAddr, regCopyInStep);
1459	#if ORIG_DTYPE_X == DT_UINT32
1460	            mask = Reg::UpdateMask<MMT>(count);
1461	            Reg::Cast<MMT, int64_t, trait1>(vregMid1, (Reg::RegTensor<int64_t>&)vregIn1, maskAll);
1462	            Reg::Cast<MMT, int64_t, trait1>(vregMid2, (Reg::RegTensor<int64_t>&)vregIn2, maskAll);
1463	#else
1464	            mask = Reg::UpdateMask<MDT>(count);
1465	            Reg::Cast<MMT, MST, trait1>(vregMid1, vregIn1, maskAll);
1466	            Reg::Cast<MMT, MST, trait1>(vregMid2, vregIn2, maskAll);
1467	#endif
1468	
1469	            Reg::DeInterleave<MMT>(vregDeinter, vregDeinterNoUse, vregMid1, vregMid2);
1470	#if ORIG_DTYPE_Y == DT_FLOAT4_E2M1
1471	            Reg::Cast<fp4x2_e2m1_t, MMT, trait2>((Reg::RegTensor<fp4x2_e2m1_t>&)vregOut, vregDeinter, maskAll);
1472	#elif ORIG_DTYPE_Y == DT_FLOAT4_E1M2
1473	            Reg::Cast<fp4x2_e1m2_t, MMT, trait2>((Reg::RegTensor<fp4x2_e1m2_t>&)vregOut, vregDeinter, maskAll);
1474	#else
1475	            Reg::Cast<MDT, MMT, trait2>(vregOut, vregDeinter, maskAll);
1476	#endif
1477	            Reg::DataCopy<MDT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, vregOut, regCopyOutStep, mask);
1478	        }
1479	    }
1480	
1481	    inQueueX_.FreeTensor(xLocal);
1482	    outQueue_.EnQue(yLocal);
1483	}
1484	
1485	template <int id, typename ST, typename DT, typename MST, typename MMT, typename MDT, LoadDist ldDist, StoreDist stDist,
1486	          RoundMode castMode1, RoundMode castMode2, int32_t RegCopyInStep, int32_t RegCopyOutStep,
1487	          int64_t OneLoopCopyInBitSize, int64_t InputTypeBitSize>
1488	__aicore__ inline void
1489	CastMicro<id, ST, DT, MST, MMT, MDT, ldDist, stDist, castMode1, castMode2, RegCopyInStep, RegCopyOutStep,
1490	          OneLoopCopyInBitSize, InputTypeBitSize>::ComputeCastCastDeinterCast(const int64_t& len, uint16_t regLoop)
1491	{
1492	    auto xLocal = inQueueX_.template DeQue<ST>();
1493	    auto yLocal = outQueue_.template AllocTensor<DT>();
1494	    __ubuf__ MST* srcAddr = (__ubuf__ MST*)xLocal.GetPhyAddr();
1495	    __ubuf__ MDT* dstAddr = (__ubuf__ MDT*)yLocal.GetPhyAddr();
1496	    int32_t regCopyInStep = RegCopyInStep;
1497	    int32_t regCopyOutStep = RegCopyOutStep;
1498	    uint32_t count = static_cast<uint32_t>(len);
1499	
1500	    // fp8 to fp32
1501	    static constexpr Reg::CastTrait trait1 = {RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING,
1502	                                              RoundMode::UNKNOWN};
1503	    // fp32 to bf16
1504	    static constexpr Reg::CastTrait trait2 = {RegLayout::ZERO, SatMode::NO_SAT, MaskMergeMode::ZEROING,
1505	                                              RoundMode::CAST_RINT};
1506	    // bf16 to fp4
1507	    static constexpr Reg::CastTrait trait3 = {RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING,
1508	                                              RoundMode::CAST_RINT};
1509	
1510	    __VEC_SCOPE__
1511	    {
1512	        Reg::RegTensor<MST> vregIn1;
1513	        Reg::RegTensor<MST> vregIn2;
1514	        Reg::RegTensor<MMT> vregMid1;
1515	        Reg::RegTensor<MMT> vregMid2;
1516	        Reg::RegTensor<bfloat16_t> vregMidBf1;
1517	        Reg::RegTensor<bfloat16_t> vregMidBf2;
1518	        Reg::RegTensor<bfloat16_t> vregDeinter;
1519	        Reg::RegTensor<bfloat16_t> vregDeinterNoUse;
1520	        Reg::RegTensor<MDT> vregOut;
1521	        Reg::MaskReg maskAll = Reg::CreateMask<uint8_t>();
1522	
1523	        for (uint16_t loopIdx = 0; loopIdx < regLoop; loopIdx++) {
1524	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn1, srcAddr, regCopyInStep);
1525	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn2, srcAddr, regCopyInStep);
1526	            Reg::Cast<MMT, MST, trait1>(vregMid1, vregIn1, maskAll);
1527	            Reg::Cast<MMT, MST, trait1>(vregMid2, vregIn2, maskAll);
1528	            Reg::Cast<bfloat16_t, MMT, trait2>(vregMidBf1, vregMid1, maskAll);
1529	            Reg::Cast<bfloat16_t, MMT, trait2>(vregMidBf2, vregMid2, maskAll);
1530	            Reg::DeInterleave<bfloat16_t>(vregDeinter, vregDeinterNoUse, vregMidBf1, vregMidBf2);
1531	#if ORIG_DTYPE_Y == DT_FLOAT4_E2M1
1532	            Reg::Cast<fp4x2_e2m1_t, bfloat16_t, trait3>((Reg::RegTensor<fp4x2_e2m1_t>&)vregOut, vregDeinter, maskAll);
1533	#elif ORIG_DTYPE_Y == DT_FLOAT4_E1M2
1534	            Reg::Cast<fp4x2_e1m2_t, bfloat16_t, trait3>((Reg::RegTensor<fp4x2_e1m2_t>&)vregOut, vregDeinter, maskAll);
1535	#else
1536	            Reg::Cast<MDT, bfloat16_t, trait3>(vregOut, vregDeinter, maskAll);
1537	#endif
1538	            // 输入fp8，ub former按照VL/sizeof(input)算的对齐，输出的ub buffer按照former分配内存，足够大，
1539	            // 而且拷出使用的是4字节转1字节转出，实际每次VF循环数据量是VL/4 *2，所以拷出ub可以直接用maskAll
1540	            Reg::DataCopy<MDT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, vregOut, regCopyOutStep, maskAll);
1541	        }
1542	    }
1543	
1544	    inQueueX_.FreeTensor(xLocal);
1545	    outQueue_.EnQue(yLocal);
1546	}
1547	
1548	template <int id, typename ST, typename DT, typename MST, typename MMT, typename MDT, LoadDist ldDist, StoreDist stDist,
1549	          RoundMode castMode1, RoundMode castMode2, int32_t RegCopyInStep, int32_t RegCopyOutStep,
1550	          int64_t OneLoopCopyInBitSize, int64_t InputTypeBitSize>
1551	__aicore__ inline void
1552	CastMicro<id, ST, DT, MST, MMT, MDT, ldDist, stDist, castMode1, castMode2, RegCopyInStep, RegCopyOutStep,
1553	          OneLoopCopyInBitSize, InputTypeBitSize>::ComputeCastInterCastCast(const int64_t& len, uint16_t regLoop)
1554	{
1555	    auto xLocal = inQueueX_.template DeQue<ST>();
1556	    auto yLocal = outQueue_.template AllocTensor<DT>();
1557	    __ubuf__ MST* srcAddr = (__ubuf__ MST*)xLocal.GetPhyAddr();
1558	    __ubuf__ MDT* dstAddr = (__ubuf__ MDT*)yLocal.GetPhyAddr();
1559	    int32_t regCopyInStep = RegCopyInStep;
1560	    int32_t regCopyOutStep = RegCopyOutStep;
1561	    uint32_t count = static_cast<uint32_t>(len);
1562	    bfloat16_t zeroValue = 0;
1563	
1564	    // fp4 to bf16
1565	    static constexpr Reg::CastTrait trait1 = {RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING,
1566	                                              RoundMode::UNKNOWN};
1567	    // bf16 to fp32
1568	    static constexpr Reg::CastTrait trait2 = {RegLayout::ZERO, SatMode::UNKNOWN, MaskMergeMode::ZEROING,
1569	                                              RoundMode::UNKNOWN};
1570	    // fp32 to fp8
1571	#if ORIG_DTYPE_Y == DT_HIFLOAT8
1572	    static constexpr Reg::CastTrait trait3 = {RegLayout::ZERO, SatMode::NO_SAT, MaskMergeMode::ZEROING,
1573	                                              RoundMode::CAST_ROUND};
1574	#else
1575	    static constexpr Reg::CastTrait trait3 = {RegLayout::ZERO, SatMode::NO_SAT, MaskMergeMode::ZEROING,
1576	                                              RoundMode::CAST_RINT};
1577	#endif
1578	
1579	    __VEC_SCOPE__
1580	    {
1581	        Reg::RegTensor<MST> vregIn;
1582	        Reg::RegTensor<bfloat16_t> vregMidBf;
1583	        Reg::RegTensor<MMT> vregMid1;
1584	        Reg::RegTensor<MMT> vregMid2;
1585	        Reg::RegTensor<MDT> vregOut1;
1586	        Reg::RegTensor<MDT> vregOut2;
1587	        Reg::MaskReg maskAll = Reg::CreateMask<uint8_t>();
1588	        Reg::RegTensor<bfloat16_t> vregZero;
1589	        Reg::Duplicate(vregZero, zeroValue);
1590	        Reg::RegTensor<bfloat16_t> vregInter1;
1591	        Reg::RegTensor<bfloat16_t> vregInter2;
1592	
1593	        for (uint16_t loopIdx = 0; loopIdx < regLoop; loopIdx++) {
1594	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn, srcAddr, regCopyInStep);
1595	#if ORIG_DTYPE_X == DT_FLOAT4_E2M1
1596	            Reg::Cast<bfloat16_t, fp4x2_e2m1_t, trait1>(vregMidBf, (Reg::RegTensor<fp4x2_e2m1_t>&)vregIn, maskAll);
1597	#elif ORIG_DTYPE_X == DT_FLOAT4_E1M2
1598	            Reg::Cast<bfloat16_t, fp4x2_e1m2_t, trait1>(vregMidBf, (Reg::RegTensor<fp4x2_e1m2_t>&)vregIn, maskAll);
1599	#else
1600	            Reg::Cast<bfloat16_t, MST, trait1>(vregMidBf, vregIn, maskAll);
1601	#endif
1602	            Reg::Interleave<bfloat16_t>(vregInter1, vregInter2, vregMidBf, vregZero);
1603	            Reg::Cast<MMT, bfloat16_t, trait2>(vregMid1, vregInter1, maskAll);
1604	            Reg::Cast<MMT, bfloat16_t, trait2>(vregMid2, vregInter2, maskAll);
1605	#if ORIG_DTYPE_Y == DT_HIFLOAT8
1606	            Reg::Cast<hifloat8_t, MMT, trait3>((Reg::RegTensor<hifloat8_t>&)vregOut1, vregMid1, maskAll);
1607	            Reg::Cast<hifloat8_t, MMT, trait3>((Reg::RegTensor<hifloat8_t>&)vregOut2, vregMid2, maskAll);
1608	#elif ORIG_DTYPE_Y == DT_FLOAT8_E5M2
1609	            Reg::Cast<fp8_e5m2_t, MMT, trait3>((Reg::RegTensor<fp8_e5m2_t>&)vregOut1, vregMid1, maskAll);
1610	            Reg::Cast<fp8_e5m2_t, MMT, trait3>((Reg::RegTensor<fp8_e5m2_t>&)vregOut2, vregMid2, maskAll);
1611	#elif ORIG_DTYPE_Y == DT_FLOAT8_E4M3FN
1612	            Reg::Cast<fp8_e4m3fn_t, MMT, trait3>((Reg::RegTensor<fp8_e4m3fn_t>&)vregOut1, vregMid1, maskAll);
1613	            Reg::Cast<fp8_e4m3fn_t, MMT, trait3>((Reg::RegTensor<fp8_e4m3fn_t>&)vregOut2, vregMid2, maskAll);
1614	#endif
1615	            // 输入fp4，ub former按照VL/sizeof(input)算的对齐，输出的ub buffer按照former分配内存，足够大，
1616	            // 而且拷出使用的是4字节转1字节转出，实际每次VF循环数据量是VL/4 *2，所以拷出ub可以直接用maskAll
1617	            Reg::DataCopy<MDT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, vregOut1, regCopyOutStep, maskAll);
1618	            Reg::DataCopy<MDT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, vregOut2, regCopyOutStep, maskAll);
1619	        }
1620	    }
1621	
1622	    inQueueX_.FreeTensor(xLocal);
1623	    outQueue_.EnQue(yLocal);
1624	}
1625	
1626	template <int id, typename ST, typename DT, typename MST, typename MMT, typename MDT, LoadDist ldDist, StoreDist stDist,
1627	          RoundMode castMode1, RoundMode castMode2, int32_t RegCopyInStep, int32_t RegCopyOutStep,
1628	          int64_t OneLoopCopyInBitSize, int64_t InputTypeBitSize>
1629	__aicore__ inline void
1630	CastMicro<id, ST, DT, MST, MMT, MDT, ldDist, stDist, castMode1, castMode2, RegCopyInStep, RegCopyOutStep,
1631	          OneLoopCopyInBitSize, InputTypeBitSize>::ComputeDeinterShift(const int64_t& len, uint16_t regLoop)
1632	{
1633	    auto xLocal = inQueueX_.template DeQue<ST>();
1634	    auto yLocal = outQueue_.template AllocTensor<DT>();
1635	    __ubuf__ MST* srcAddr = (__ubuf__ MST*)xLocal.GetPhyAddr();
1636	    __ubuf__ MDT* dstAddr = (__ubuf__ MDT*)yLocal.GetPhyAddr();
1637	    int32_t regCopyInStep = RegCopyInStep;
1638	    int32_t regCopyOutStep = RegCopyOutStep;
1639	    uint32_t count = static_cast<uint32_t>(len);
1640	
1641	    __VEC_SCOPE__
1642	    {
1643	        Reg::RegTensor<MST> vregIn1;
1644	        Reg::RegTensor<MST> vregIn2;
1645	        Reg::RegTensor<MMT> vregDeinter1;
1646	        Reg::RegTensor<MMT> vregDeinter2;
1647	        Reg::RegTensor<MMT> vregMid1;
1648	        Reg::RegTensor<MMT> vregMid2;
1649	        Reg::RegTensor<MMT> vreg4Bit;
1650	        Reg::RegTensor<MMT> vregOut;
1651	        Reg::MaskReg mask;
1652	        Reg::MaskReg maskAll = Reg::CreateMask<uint8_t>();
1653	        Reg::Duplicate(vreg4Bit, B4_MASK);
1654	
1655	        for (uint16_t loopIdx = 0; loopIdx < regLoop; loopIdx++) {
1656	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn1, srcAddr, regCopyInStep);
1657	            Reg::DataCopy<MST, Reg::PostLiteral::POST_MODE_UPDATE, ldDist>(vregIn2, srcAddr, regCopyInStep);
1658	
1659	            Reg::DeInterleave<MMT>(vregDeinter1, vregDeinter2, vregIn1, vregIn2);
1660	            Reg::And<MMT, Reg::MaskMergeMode::ZEROING>(vregMid1, vregDeinter1, vreg4Bit, maskAll);
1661	            Reg::ShiftLefts(vregMid2, vregDeinter2, SHIFT_FOUR_BITS, maskAll);
1662	            Reg::Or<MMT, Reg::MaskMergeMode::ZEROING>(vregOut, vregMid1, vregMid2, maskAll);
1663	
1664	            mask = Reg::UpdateMask<MMT>(count);
1665	            Reg::DataCopy<MMT, Reg::PostLiteral::POST_MODE_UPDATE, stDist>(dstAddr, vregOut, regCopyOutStep, mask);
1666	        }
1667	    }
1668	
1669	    inQueueX_.FreeTensor(xLocal);
1670	    outQueue_.EnQue(yLocal);
1671	}
