1673	template <int id, typename ST, typename DT, typename MST, typename MMT, typename MDT, LoadDist ldDist, StoreDist stDist,
1674	          RoundMode castMode1, RoundMode castMode2, int32_t RegCopyInStep, int32_t RegCopyOutStep,
1675	          int64_t OneLoopCopyInBitSize, int64_t InputTypeBitSize>
1676	__aicore__ inline void
1677	CastMicro<id, ST, DT, MST, MMT, MDT, ldDist, stDist, castMode1, castMode2, RegCopyInStep, RegCopyOutStep,
1678	          OneLoopCopyInBitSize, InputTypeBitSize>::CopyOut(const int64_t& gmOffset)
1679	{
1680	    auto yLocalOut = outQueue_.template DeQue<DT>();
1681	    DataCopyPad(yGm_[gmOffset], yLocalOut, dataCopyOutParams_);
1682	    outQueue_.FreeTensor(yLocalOut);
1683	}
1684	
1685	template <int id, typename ST, typename DT, typename MST, typename MMT, typename MDT, LoadDist ldDist, StoreDist stDist,
1686	          RoundMode castMode1, RoundMode castMode2, int32_t RegCopyInStep, int32_t RegCopyOutStep,
1687	          int64_t OneLoopCopyInBitSize, int64_t InputTypeBitSize>
1688	__aicore__ inline void CastMicro<id, ST, DT, MST, MMT, MDT, ldDist, stDist, castMode1, castMode2, RegCopyInStep,
1689	                                 RegCopyOutStep, OneLoopCopyInBitSize, InputTypeBitSize>::Process()
1690	{
1691	    bool isLastBlockFlag = (blockIdx_ == derived_.blockNum - 1);
1692	    int64_t loopNum = isLastBlockFlag ? derived_.ubLoopOfTailBlock : derived_.ubLoopOfFormerBlock;
1693	    int64_t tailNum = isLastBlockFlag ? derived_.ubTailOfTailBlock : derived_.ubTailOfFormerBlock;
1694	    int64_t tailRegLoop = isLastBlockFlag ? ubTailOfTailRegLoop_ : ubTailOfFormerRegLoop_;
1695	
1696	#if ORIG_DTYPE_X == DT_FLOAT4_E2M1 || ORIG_DTYPE_X == DT_FLOAT4_E1M2
1697	    int64_t xRealFormer = tilingData_->ubFormer / B2_BITS;
1698	#else
1699	    int64_t xRealFormer = tilingData_->ubFormer;
1700	#endif
1701	
1702	#if ORIG_DTYPE_Y == DT_FLOAT4_E2M1 || ORIG_DTYPE_Y == DT_FLOAT4_E1M2 || ORIG_DTYPE_Y == DT_INT4
1703	    int64_t yRealFormer = tilingData_->ubFormer / B2_BITS;
1704	#else
1705	    int64_t yRealFormer = tilingData_->ubFormer;
1706	#endif
1707	
1708	    dataCopyInParams_.blockLen = xRealFormer * sizeof(ST);
1709	    dataCopyOutParams_.blockLen = yRealFormer * sizeof(DT);
1710	    int64_t xGmOffset = 0;
1711	    int64_t yGmOffset = 0;
1712	    for (int64_t i = 0; i < loopNum - 1; ++i) {
1713	        CopyIn(xGmOffset);
1714	        Compute(tilingData_->ubFormer, static_cast<uint16_t>(ubFormerRegLoop_));
1715	        CopyOut(yGmOffset);
1716	        xGmOffset += xRealFormer;
1717	        yGmOffset += yRealFormer;
1718	    }
1719	
1720	#if ORIG_DTYPE_X == DT_FLOAT4_E2M1 || ORIG_DTYPE_X == DT_FLOAT4_E1M2
1721	    dataCopyInParams_.blockLen = (tailNum + 1) / B2_BITS * sizeof(ST);
1722	#else
1723	    dataCopyInParams_.blockLen = tailNum * sizeof(ST);
1724	#endif
1725	
1726	#if ORIG_DTYPE_Y == DT_FLOAT4_E2M1 || ORIG_DTYPE_Y == DT_FLOAT4_E1M2 || ORIG_DTYPE_Y == DT_INT4
1727	    dataCopyOutParams_.blockLen = (tailNum + 1) / B2_BITS * sizeof(DT);
1728	#else
1729	    dataCopyOutParams_.blockLen = tailNum * sizeof(DT);
1730	#endif
1731	
1732	    CopyIn(xGmOffset);
1733	    Compute(tailNum, static_cast<uint16_t>(tailRegLoop));
1734	    CopyOut(yGmOffset);
1735	}
